const lamp = {
  name: "lamp",
  describe(state) {
    return `${this.name} is ${state}`;
  },
};

const radio = { name: "radio" };

const lampIs = lamp.describe.bind(lamp);
const radioOn = lamp.describe.bind(radio, "on");

console.log(lampIs("off"));
console.log(radioOn());
console.log(radioOn("off"));
